package com.t3h.uniqlo.controller;

import com.t3h.uniqlo.model.dto.ProductionDTO;
import com.t3h.uniqlo.model.response.ProductionResponse;
import com.t3h.uniqlo.service.ProductionService;
import com.t3h.uniqlo.utils.Constant;
import com.t3h.uniqlo.utils.StringUtils;
import jakarta.servlet.RequestDispatcher;
import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import lombok.extern.slf4j.Slf4j;

import java.io.IOException;

@Slf4j
@WebServlet(name = "ProductionsServlet", urlPatterns = "/productions")
public class ProductionsServlet extends HttpServlet {

    private final ProductionService productionService = new ProductionService();

    // ===================== GET: hiển thị danh sách / form sửa =====================
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        req.setCharacterEncoding("UTF-8");

        String action = req.getParameter("action");

        // Nếu action = edit -> load sản phẩm theo id để điền vào modal
        if ("edit".equals(action)) {
            Integer id = StringUtils.getInteger(req.getParameter("id"));
            if (id != null && id > 0) {
                ProductionDTO editProduct = productionService.findById(id);
                req.setAttribute("editProduct", editProduct);
            }
        }

        // Lấy tham số phân trang / tìm kiếm
        Integer pageSize  = StringUtils.getInteger(req.getParameter("pageSize"));
        Integer pageIndex = StringUtils.getInteger(req.getParameter("currentPage"));
        String  keyword   = req.getParameter("keySearch") != null ? req.getParameter("keySearch").trim() : "";
        Integer categoryId = StringUtils.getInteger(req.getParameter("categoryId"));
        Integer colorId    = StringUtils.getInteger(req.getParameter("colorId"));

        if (pageIndex == -1) pageIndex = Constant.DEFAULT_PAGE;
        if (pageSize  == -1) pageSize  = Constant.DEFAULT_PAGE_SIZE;

        // Lấy danh sách sản phẩm
        ProductionResponse response = productionService.findByCondition(pageSize, pageIndex, keyword, colorId, categoryId);

        // Bind attributes vào request
        req.setAttribute("productions",  response.getData());
        req.setAttribute("keySearch",    keyword);
        req.setAttribute("categoryId",   categoryId);
        req.setAttribute("colorId",      colorId);
        req.setAttribute("totalPages",   response.getTotalPages());
        req.setAttribute("pageSize",     pageSize);
        req.setAttribute("currentPage",  pageIndex);

        // Dropdown categories và colors từ DB
        req.setAttribute("categories", productionService.getCategories());
        req.setAttribute("colors",     productionService.getColors());

        RequestDispatcher rd = getServletContext().getRequestDispatcher("/WEB-INF/views/productions.jsp");
        rd.forward(req, resp);
    }

    // ===================== POST: xử lý thêm / sửa / xóa =====================
    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        req.setCharacterEncoding("UTF-8");

        String action = req.getParameter("action");
        String contextPath = req.getContextPath();

        if ("create".equals(action)) {
            String  name         = req.getParameter("name");
            Integer categoryId   = StringUtils.getInteger(req.getParameter("category_id"));
            String  description  = req.getParameter("description");
            String  materialInfo = req.getParameter("material_info");
            String  avatar       = req.getParameter("avatar");
            if (avatar == null || avatar.isBlank()) {
                avatar = "https://placehold.co/400x500/EEE/333?text=No+Image";
            }

            try {
                productionService.save(name, categoryId, description, materialInfo, avatar, null);
                resp.sendRedirect(contextPath + "/productions?success=created");
            } catch (Exception e) {
                log.error("Lỗi khi tạo sản phẩm", e);
                resp.sendRedirect(contextPath + "/productions?error=create_failed");
            }

        } else if ("update".equals(action)) {
            Integer id           = StringUtils.getInteger(req.getParameter("id"));
            String  name         = req.getParameter("name");
            Integer categoryId   = StringUtils.getInteger(req.getParameter("category_id"));
            String  description  = req.getParameter("description");
            String  materialInfo = req.getParameter("material_info");
            String  avatar       = req.getParameter("avatar");

            try {
                productionService.save(name, categoryId, description, materialInfo, avatar, id);
                resp.sendRedirect(contextPath + "/productions?success=updated");
            } catch (Exception e) {
                log.error("Lỗi khi cập nhật sản phẩm id={}", id, e);
                resp.sendRedirect(contextPath + "/productions?error=update_failed");
            }

        } else if ("delete".equals(action)) {
            Integer id = StringUtils.getInteger(req.getParameter("id"));
            try {
                productionService.delete(id);
                resp.sendRedirect(contextPath + "/productions?success=deleted");
            } catch (Exception e) {
                log.error("Lỗi khi xóa sản phẩm id={}", id, e);
                resp.sendRedirect(contextPath + "/productions?error=delete_failed");
            }

        } else {
            resp.sendRedirect(contextPath + "/productions");
        }
    }
}

package com.t3h.uniqlo.controller;

import com.t3h.uniqlo.model.dto.ProductionDTO;
import com.t3h.uniqlo.model.response.ProductionResponse;
import com.t3h.uniqlo.service.ProductionService;
import com.t3h.uniqlo.utils.Constant;
import com.t3h.uniqlo.utils.StringUtils;
import jakarta.servlet.RequestDispatcher;
import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import lombok.extern.slf4j.Slf4j;

import java.io.IOException;

@Slf4j
@WebServlet(name = "ProductionsServlet", urlPatterns = "/productions")
public class ProductionsServlet extends HttpServlet {

    private static final String VIEW_PATH = "/WEB-INF/views/productions.jsp";

    private static final String ATTR_EDIT_PRODUCT = "editProduct";
    private static final String ATTR_PRODUCTIONS = "productions";
    private static final String ATTR_KEY_SEARCH = "keySearch";
    private static final String ATTR_CATEGORY_ID = "categoryId";
    private static final String ATTR_COLOR_ID = "colorId";
    private static final String ATTR_TOTAL_PAGES = "totalPages";
    private static final String ATTR_PAGE_SIZE = "pageSize";
    private static final String ATTR_CURRENT_PAGE = "currentPage";
    private static final String ATTR_CATEGORIES = "categories";
    private static final String ATTR_COLORS = "colors";

    private static final String PARAM_ACTION = "action";
    private static final String PARAM_ID = "id";
    private static final String PARAM_PAGE_SIZE = "pageSize";
    private static final String PARAM_CURRENT_PAGE = "currentPage";
    private static final String PARAM_KEY_SEARCH = "keySearch";
    private static final String PARAM_CATEGORY_ID = "categoryId";
    private static final String PARAM_COLOR_ID = "colorId";

    private static final String PARAM_NAME = "name";
    private static final String PARAM_CATEGORY_ID_FORM = "category_id";
    private static final String PARAM_DESCRIPTION = "description";
    private static final String PARAM_MATERIAL_INFO = "material_info";
    private static final String PARAM_AVATAR = "avatar";

    private static final String ACTION_EDIT = "edit";
    private static final String ACTION_CREATE = "create";
    private static final String ACTION_UPDATE = "update";
    private static final String ACTION_DELETE = "delete";

    private final ProductionService productionService = new ProductionService();

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        setUtf8(req);

        String action = trimToNull(req.getParameter(PARAM_ACTION));
        if (ACTION_EDIT.equals(action)) {
            bindEditProductIfPresent(req);
        }

        bindListPage(req);
        forwardToView(req, resp);
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        setUtf8(req);

        String action = trimToNull(req.getParameter(PARAM_ACTION));
        if (ACTION_CREATE.equals(action)) {
            handleCreate(req, resp);
            return;
        }
        if (ACTION_UPDATE.equals(action)) {
            handleUpdate(req, resp);
            return;
        }
        if (ACTION_DELETE.equals(action)) {
            handleDelete(req, resp);
            return;
        }

        redirectToList(resp, req.getContextPath());
    }

    private void bindEditProductIfPresent(HttpServletRequest req) {
        Integer id = parseOptionalInt(req, PARAM_ID);
        if (id == null || id <= 0) {
            return;
        }

        ProductionDTO editProduct = productionService.findById(id);
        req.setAttribute(ATTR_EDIT_PRODUCT, editProduct);
    }

    private void bindListPage(HttpServletRequest req) {
        ListQuery query = buildListQuery(req);

        ProductionResponse response = productionService.findByCondition(
                query.pageSize,
                query.currentPage,
                query.keyword,
                query.colorId,
                query.categoryId
        );

        req.setAttribute(ATTR_PRODUCTIONS, response.getData());
        req.setAttribute(ATTR_KEY_SEARCH, query.keyword);
        req.setAttribute(ATTR_CATEGORY_ID, query.categoryId);
        req.setAttribute(ATTR_COLOR_ID, query.colorId);
        req.setAttribute(ATTR_TOTAL_PAGES, response.getTotalPages());
        req.setAttribute(ATTR_PAGE_SIZE, query.pageSize);
        req.setAttribute(ATTR_CURRENT_PAGE, query.currentPage);

        req.setAttribute(ATTR_CATEGORIES, productionService.getCategories());
        req.setAttribute(ATTR_COLORS, productionService.getColors());
    }

    private ListQuery buildListQuery(HttpServletRequest req) {
        Integer pageSize = parseOptionalInt(req, PARAM_PAGE_SIZE);
        Integer currentPage = parseOptionalInt(req, PARAM_CURRENT_PAGE);

        int resolvedPageSize = (pageSize == null || pageSize <= 0) ? Constant.DEFAULT_PAGE_SIZE : pageSize;
        int resolvedCurrentPage = (currentPage == null || currentPage <= 0) ? Constant.DEFAULT_PAGE : currentPage;

        String keyword = trimToEmpty(req.getParameter(PARAM_KEY_SEARCH));
        Integer categoryId = parseOptionalInt(req, PARAM_CATEGORY_ID);
        Integer colorId = parseOptionalInt(req, PARAM_COLOR_ID);

        return new ListQuery(resolvedPageSize, resolvedCurrentPage, keyword, categoryId, colorId);
    }

    private void handleCreate(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        ProductionCommand cmd = buildProductionCommand(req, null);

        try {
            productionService.save(cmd.name, cmd.categoryId, cmd.description, cmd.materialInfo, cmd.avatar, null);
            redirectToList(resp, req.getContextPath(), "success=created");
        } catch (Exception e) {
            log.error("Create product failed", e);
            redirectToList(resp, req.getContextPath(), "error=create_failed");
        }
    }

    private void handleUpdate(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        Integer id = parseOptionalInt(req, PARAM_ID);
        ProductionCommand cmd = buildProductionCommand(req, id);

        try {
            productionService.save(cmd.name, cmd.categoryId, cmd.description, cmd.materialInfo, cmd.avatar, id);
            redirectToList(resp, req.getContextPath(), "success=updated");
        } catch (Exception e) {
            log.error("Update product failed: id={}", id, e);
            redirectToList(resp, req.getContextPath(), "error=update_failed");
        }
    }

    private void handleDelete(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        Integer id = parseOptionalInt(req, PARAM_ID);
        if (id == null || id <= 0) {
            redirectToList(resp, req.getContextPath(), "error=invalid_id");
            return;
        }

        try {
            productionService.delete(id);
            redirectToList(resp, req.getContextPath(), "success=deleted");
        } catch (Exception e) {
            log.error("Delete product failed: id={}", id, e);
            redirectToList(resp, req.getContextPath(), "error=delete_failed");
        }
    }

    private ProductionCommand buildProductionCommand(HttpServletRequest req, Integer id) {
        String name = trimToNull(req.getParameter(PARAM_NAME));
        Integer categoryId = parseOptionalInt(req, PARAM_CATEGORY_ID_FORM);
        String description = trimToEmpty(req.getParameter(PARAM_DESCRIPTION));
        String materialInfo = trimToEmpty(req.getParameter(PARAM_MATERIAL_INFO));
        String avatar = resolveAvatar(req.getParameter(PARAM_AVATAR));

        return new ProductionCommand(id, name, categoryId, description, materialInfo, avatar);
    }

    private String resolveAvatar(String avatarParam) {
        String avatar = trimToNull(avatarParam);
        if (avatar != null) {
            return avatar;
        }
        return "https://placehold.co/400x500/EEE/333?text=No+Image";
    }

    private void forwardToView(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        RequestDispatcher rd = getServletContext().getRequestDispatcher(VIEW_PATH);
        rd.forward(req, resp);
    }

    private void redirectToList(HttpServletResponse resp, String contextPath) throws IOException {
        resp.sendRedirect(contextPath + "/productions");
    }

    private void redirectToList(HttpServletResponse resp, String contextPath, String queryString) throws IOException {
        resp.sendRedirect(contextPath + "/productions" + (queryString == null || queryString.isBlank() ? "" : "?" + queryString));
    }

    private void setUtf8(HttpServletRequest req) throws IOException {
        req.setCharacterEncoding("UTF-8");
    }

    private Integer parseOptionalInt(HttpServletRequest req, String paramName) {
        Integer value = StringUtils.getInteger(req.getParameter(paramName));
        return (value == null || value < 0) ? null : value;
    }

    private String trimToNull(String s) {
        if (s == null) return null;
        String t = s.trim();
        return t.isEmpty() ? null : t;
    }

    private String trimToEmpty(String s) {
        return s == null ? "" : s.trim();
    }

    private record ListQuery(int pageSize, int currentPage, String keyword, Integer categoryId, Integer colorId) {}

    private record ProductionCommand(Integer id, String name, Integer categoryId, String description, String materialInfo,
                                     String avatar) {}
}
